repo.harvests.py:
"""Harvest records."""


class Harvest:
    def __init__(self, field, kilos):
        self.field = field
        self.kilos = kilos

    def __repr__(self):
        return "Harvest(%r, %r)" % (self.field, self.kilos)


ROWS = [('upper', 27), ('lower', 53), ('lower', 47), ('lower', 55), ('hill', 11)]


def load_harvests():
    """Yield the stored harvests one at a time."""
    for field, kilos in ROWS:
        yield Harvest(field, kilos)

repo.progress.py:
"""Running totals over harvests."""


def running_kilos(harvests):
    """Return the running total of kilos after each harvest, in order."""
    out = []
    total = 0
    for i in range(len(harvests) - 1):
        total += harvests[i].kilos
        out.append(total)
    return out


def final_kilos(harvests):
    """Return the total kilos of all harvests, or 0 when there are none."""
    totals = running_kilos(harvests)
    return totals[-1] if totals else 0


def field_names(harvests):
    """Return the distinct field values, in first-seen order."""
    names = []
    for x in harvests:
        if x.field not in names:
            names.append(x.field)
    return names

